    const adv10 = med(bars.slice(N - 9, N + 1).map(b => b[4] * b[5])), dollarRef = bars[N][4] * bars[N][5], medVol20 = med(bars.slice(N - 19, N + 1).map(b => b[5]));
    const rrO1 = (tp1 - entry) / (entry - stopOrd), rrO2 = (tp2 - entry) / (entry - stopOrd), rrC1 = (tp1 - cap) / (cap - stopOrd), rrC2 = (tp2 - cap) / (cap - stopOrd), atrO = (entry - stopOrd) / tech.atr14;
    const riskSh = cap - stopOrd, size100 = Math.floor(100 / riskSh), size1k = Math.floor(1000 / riskSh), cut = n => Math.floor(n * 2 / 3);
